_satellite.__registerScript('https://assets.adobedtm.com/4f105c1434ad/05fddbc767bb/3d1997c7fe71/RCa9a87bb6509149a4a562d4100ed31fac-source.min.js', "<script type=\"text/javascript\">\n  (function () {\n  window.mfLog = window.mfLog || [];\n  window._mfq = window._mfq || [];\n  window._mfq.push([\"config\", \"htmlDelay\", 2000]);\n  //Identify environment\n  window.mfHelper(\"tag\", _satellite.environment.stage)\n  \n  // Capture and send data layer info to Mouseflow\n  function captureDataLayerInfo() {\n  const adlAvailable = typeof AnalyticsDataLayer === \"object\" && AnalyticsDataLayer !== null;\n  const liveChatAvailable = typeof getLiveChatState === \"function\";\n\n  if (!adlAvailable && !liveChatAvailable) {\n    _satellite.logger.log(\"AnalyticsDataLayer and getLiveChatState() not available\");\n    return;\n  }\n\n  if (!adlAvailable) _satellite.logger.log(\"AnalyticsDataLayer not available\");\n  if (!liveChatAvailable) _satellite.logger.log(\"getLiveChatState() not available\");\n\n  // Get data layer values - DRY\n  let user = adlAvailable ? AnalyticsDataLayer.user : null;\n  let sale = adlAvailable ? AnalyticsDataLayer.sale : null;\n  let page = adlAvailable ? AnalyticsDataLayer.page : null;\n  let guid = user?.GUID && user.GUID !== \"\" ? user.GUID : null;\n  let userInfo = liveChatAvailable ? getLiveChatState() : null;\n  let kycStatus = userInfo?.userDetails?.fields?.kycstatus;\n  let userStatus = user?.status;\n  let language = page?.language;\n  let template = page?.template;\n  let saleStatus = sale?.status;\n  let saleType = sale?.type;\n    \n    // User identification\n    if (userStatus) {\n      window.mfHelper(\"setVariable\", \"User Status\", userStatus);\n    }\n    \n    // Authenticated user data\n    if (guid) {\n      window.mfHelper(\"identify\", guid);\n      // KYC Status (Available only on pages with Acquire LiveChat)\n      if (kycStatus) {\n        window.mfHelper(\"setVariable\", \"KYC Status\", kycStatus);\n      }\n    }         \n    \n    // Sale info\n    if (sale) {\n      if (saleStatus) window.mfHelper(\"tag\", \"Sale Status\", saleStatus);\n      if (saleType) window.mfHelper(\"tag\", \"Sale Type\", saleType);\n    }    \n    \n    // Page Info\n    if (template) {\n      window.mfHelper(\"tag\", \"Template\", template);\n    }\n    if (language) {\n      window.mfHelper(\"setVariable\", \"Language\", language);\n    }\n    \n    // Tells the mfHelper function to send a page identifier tag (ie,\"page:luxury-week\")\n    window.mfHelper(\"pageTag\");\n    \n    _satellite.logger.log(\"Mouseflow data layer captured\", { \n      tagsAndVariables: window.mfLog\n    });\n  }\n  \n  if (_satellite.getVar(\"ACR_OneTrust_Performance\") == \"false\") {\n    _satellite.logger.log(\"mouseflow shouldnt load and/or recording should be stopped because the user rejected performance cookies\");\n    if (window.mouseflow && window.mouseflow.isRecording()) {\n      window.mouseflow.stop();\n    }\n    return false;\n  }\n  \n  var mf = document.createElement(\"script\");\n  mf.addEventListener(\"load\", function (event) {\n    // Capture data layer info on initial load\n    captureDataLayerInfo();\n  });\n\n  var siteId = _satellite.getVar('mouseflowSiteId');\n    \n  mf.type = \"text/javascript\";\n  mf.defer = true;\n  mf.src = \"//cdn.mouseflow.com/projects/\" + siteId + \".js\";\n  document.getElementsByTagName(\"head\")[0].appendChild(mf);\n})();\n</script>");